func (registry *soundRegistry) ByID(id data.SoundID) (data.Sound, bool) {
	value, ok := registry.byID[id]
	return value, ok
}
func (registry *soundRegistry) ByName(name string) (data.Sound, bool) {
	value, ok := registry.byName[name]
	return value, ok
}
func (registry *soundRegistry) All() data.Sounds { return registry.all.Clone() }
